def dot(a, b):
    return sum(x * y for x, y in zip(a, b))

def norm(v):
    return dot(v, v) ** 0.5

def best_match(query, docs):
    # rank documents by cosine similarity
    best, best_score = None, float("-inf")
    for doc in docs:
        score = dot(query, doc["vec"])
        if score > best_score:
            best, best_score = doc, score
    return best

