import json

reply = ('Here you go: {"tags": ["a", "b"]} '
         'Next time use {"tags": [...]}.')
start = reply.find("{")
end = reply.rfind("}")
try:
    data = json.loads(reply[start:end + 1])
    print(len(data["tags"]))
except json.JSONDecodeError as e:
    print("error:", e.msg)

